def transform(grid):
    rows, cols = len(grid), len(grid[0])
    sep_color = 8

    horiz_seps = [r for r in range(rows) if all(grid[r][c] == sep_color for c in range(cols))]
    vert_seps = [c for c in range(cols) if all(grid[r][c] == sep_color for r in range(rows))]

    if not horiz_seps or not vert_seps:
        return grid

    output = [row[:] for row in grid]

    # Find pattern section - the one with non-background pixels
    # Find all sections
    section_patterns = []
    for i in range(len(horiz_seps)):
        h_start = 0 if i == 0 else horiz_seps[i-1] + 1
        h_end = horiz_seps[i]
        for j in range(len(vert_seps)):
            v_start = 0 if j == 0 else vert_seps[j-1] + 1
            v_end = vert_seps[j]

            has_pattern = False
            for r in range(h_start, h_end):
                for c in range(v_start, v_end):
                    if grid[r][c] != grid[0][0]:
                        has_pattern = True
                        break
                if has_pattern:
                    break
            section_patterns.append((i, j, h_start, h_end, v_start, v_end, has_pattern))

    # Find the source section (has_pattern = True)
    source = None
    for s in section_patterns:
        if s[6]:
            source = s
            break

    if source is None:
        return grid

    src_hr, src_vr, src_h_start, src_h_end, src_v_start, src_v_end, _ = source

    # Copy pattern to all other sections
    for s in section_patterns:
        if s is source:
            continue
        s_hr, s_vr, s_h_start, s_h_end, s_v_start, s_v_end, _ = s

        for r in range(src_h_start, src_h_end):
            for c in range(src_v_start, src_v_end):
                if grid[r][c] != grid[0][0]:
                    tr = r - src_h_start + s_h_start
                    tc = c - src_v_start + s_v_start
                    if s_h_start <= tr < s_h_end and s_v_start <= tc < s_v_end:
                        output[tr][tc] = grid[r][c]

    return output
